def roa(profit_margin, asset_turnover):
    return profit_margin * asset_turnover

companies = {
    "John Lewis": (0.074, 1.39),   # (profit margin, asset turnover)
    "LVMH":       (0.224, 0.51),
}

for name, (pm, at) in companies.items():
    print(f"{name:12s}  margin={pm:6.1%}  turnover={at:.2f}  ->  ROA={roa(pm, at):5.1%}")
